// Stock Data Visualization with D3.js v6
// Bubble chart with sector clustering and interactive data table

let stockData = [];
let selectedTicker = null;

// Color scale for sectors
const sectorColors = {
    'Information Technology': '#3498db',
    'Industry': '#e74c3c',
    'Energy': '#f39c12',
    'Financial': '#2ecc71',
    'ETF': '#95a5a6'
};

// Initialize the visualization
async function init() {
    try {
        // Load stock descriptions data
        const data = await d3.csv('data/stock-descriptions.csv');

        // Process data: convert marketCap to number, handle ETFs
        stockData = data.map(d => ({
            ticker: d.ticker,
            sector: d.sector,
            fullName: d['full name'],
            marketCap: d.marketCap === '' ? null : +d.marketCap,
            isETF: d.sector === 'ETF'
        }));

        // Sort data by ticker for deterministic rendering
        stockData.sort((a, b) => a.ticker.localeCompare(b.ticker));

        // Create visualizations
        createBubbleChart();
        createDataTable();

    } catch (error) {
        console.error('Error loading data:', error);
    }
}

// Format market cap for display
function formatMarketCap(value) {
    if (!value) return 'N/A';
    if (value >= 1e12) return (value / 1e12).toFixed(2) + 'T';
    if (value >= 1e9) return (value / 1e9).toFixed(2) + 'B';
    if (value >= 1e6) return (value / 1e6).toFixed(2) + 'M';
    return value.toFixed(2);
}

// Create bubble chart with force simulation
function createBubbleChart() {
    const container = d3.select('#bubble-chart');
    const width = 800;
    const height = 700;

    // Clear any existing content
    container.selectAll('*').remove();

    const svg = container
        .append('svg')
        .attr('width', width)
        .attr('height', height)
        .attr('viewBox', `0 0 ${width} ${height}`);

    // Calculate bubble radius based on market cap
    const maxMarketCap = d3.max(stockData.filter(d => d.marketCap), d => d.marketCap);
    const minMarketCap = d3.min(stockData.filter(d => d.marketCap), d => d.marketCap);

    // Size scale for bubbles
    const radiusScale = d3.scaleSqrt()
        .domain([minMarketCap, maxMarketCap])
        .range([15, 60]);

    // ETF uniform size
    const etfRadius = 20;

    // Assign radius to each stock
    stockData.forEach(d => {
        d.radius = d.isETF ? etfRadius : radiusScale(d.marketCap);
    });

    // Get unique sectors for positioning
    const sectors = Array.from(new Set(stockData.map(d => d.sector))).sort();

    // Create sector centers for clustering
    const sectorCenters = {};
    const cols = 3;
    const rows = Math.ceil(sectors.length / cols);
    const xSpacing = width / (cols + 1);
    const ySpacing = height / (rows + 1);

    sectors.forEach((sector, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        sectorCenters[sector] = {
            x: xSpacing * (col + 1),
            y: ySpacing * (row + 1)
        };
    });

    // Force simulation
    const simulation = d3.forceSimulation(stockData)
        .force('x', d3.forceX(d => sectorCenters[d.sector].x).strength(0.5))
        .force('y', d3.forceY(d => sectorCenters[d.sector].y).strength(0.5))
        .force('collide', d3.forceCollide(d => d.radius + 2))
        .force('charge', d3.forceManyBody().strength(-5))
        .stop();

    // Run simulation to completion for deterministic positioning
    for (let i = 0; i < 300; i++) {
        simulation.tick();
    }

    // Create bubbles group
    const bubbles = svg.selectAll('.bubble')
        .data(stockData)
        .enter()
        .append('g')
        .attr('class', 'bubble')
        .attr('transform', d => `translate(${d.x},${d.y})`)
        .style('cursor', d => d.isETF ? 'default' : 'pointer')
        .on('click', function(event, d) {
            if (!d.isETF) {
                handleBubbleClick(d);
            }
        })
        .on('mouseover', function(event, d) {
            if (!d.isETF) {
                d3.select('#tooltip')
                    .classed('visible', true)
                    .html(`
                        <strong>${d.ticker}</strong><br/>
                        ${d.fullName}<br/>
                        Sector: ${d.sector}<br/>
                        Market Cap: ${formatMarketCap(d.marketCap)}
                    `)
                    .style('left', (event.pageX + 10) + 'px')
                    .style('top', (event.pageY - 10) + 'px');

                // Highlight bubble
                d3.select(this).select('circle')
                    .attr('stroke', '#000')
                    .attr('stroke-width', 3);
            }
        })
        .on('mouseout', function(event, d) {
            d3.select('#tooltip').classed('visible', false);

            // Remove highlight if not selected
            if (selectedTicker !== d.ticker) {
                d3.select(this).select('circle')
                    .attr('stroke', '#fff')
                    .attr('stroke-width', 2);
            }
        });

    // Add circles
    bubbles.append('circle')
        .attr('r', d => d.radius)
        .attr('fill', d => sectorColors[d.sector])
        .attr('stroke', '#fff')
        .attr('stroke-width', 2)
        .attr('opacity', 0.8);

    // Add labels
    bubbles.append('text')
        .attr('text-anchor', 'middle')
        .attr('dy', '0.3em')
        .attr('fill', '#fff')
        .attr('font-size', d => Math.min(d.radius / 2.5, 14) + 'px')
        .attr('font-weight', 'bold')
        .attr('pointer-events', 'none')
        .text(d => d.ticker);

    // Add legend
    createLegend(svg, sectors, width);
}

// Create legend for sectors
function createLegend(svg, sectors, width) {
    const legend = svg.append('g')
        .attr('class', 'legend')
        .attr('transform', `translate(${width - 150}, 20)`);

    legend.append('text')
        .attr('x', 0)
        .attr('y', 0)
        .attr('font-weight', 'bold')
        .attr('font-size', '14px')
        .text('Sectors');

    const legendItems = legend.selectAll('.legend-item')
        .data(sectors)
        .enter()
        .append('g')
        .attr('class', 'legend-item')
        .attr('transform', (d, i) => `translate(0, ${i * 25 + 20})`);

    legendItems.append('circle')
        .attr('r', 8)
        .attr('fill', d => sectorColors[d])
        .attr('opacity', 0.8);

    legendItems.append('text')
        .attr('x', 15)
        .attr('y', 4)
        .attr('font-size', '12px')
        .text(d => d);
}

// Create data table
function createDataTable() {
    const tableContainer = d3.select('#data-table');

    // Clear any existing content
    tableContainer.selectAll('*').remove();

    const table = tableContainer.append('table');

    // Create header
    const thead = table.append('thead');
    const headerRow = thead.append('tr');

    headerRow.selectAll('th')
        .data(['Ticker', 'Company Name', 'Sector', 'Market Cap'])
        .enter()
        .append('th')
        .text(d => d);

    // Create body
    const tbody = table.append('tbody');

    const rows = tbody.selectAll('tr')
        .data(stockData)
        .enter()
        .append('tr')
        .attr('class', 'table-row')
        .attr('data-ticker', d => d.ticker)
        .style('cursor', 'pointer')
        .on('click', function(event, d) {
            handleTableRowClick(d);
        });

    // Add cells
    rows.append('td')
        .attr('class', 'ticker-cell')
        .text(d => d.ticker);

    rows.append('td')
        .text(d => d.fullName);

    rows.append('td')
        .text(d => d.sector);

    rows.append('td')
        .attr('class', 'market-cap-cell')
        .text(d => formatMarketCap(d.marketCap));
}

// Handle bubble click
function handleBubbleClick(data) {
    selectedTicker = data.ticker;

    // Update bubble selection
    d3.selectAll('.bubble circle')
        .attr('stroke', '#fff')
        .attr('stroke-width', 2);

    d3.selectAll('.bubble')
        .filter(d => d.ticker === data.ticker)
        .select('circle')
        .attr('stroke', '#000')
        .attr('stroke-width', 4);

    // Update table selection
    highlightTableRow(data.ticker);
}

// Handle table row click
function handleTableRowClick(data) {
    selectedTicker = data.ticker;

    // Update table selection
    highlightTableRow(data.ticker);

    // Update bubble selection (only if not ETF)
    if (!data.isETF) {
        d3.selectAll('.bubble circle')
            .attr('stroke', '#fff')
            .attr('stroke-width', 2);

        d3.selectAll('.bubble')
            .filter(d => d.ticker === data.ticker)
            .select('circle')
            .attr('stroke', '#000')
            .attr('stroke-width', 4);
    }
}

// Highlight table row
function highlightTableRow(ticker) {
    d3.selectAll('.table-row')
        .classed('selected', false);

    d3.selectAll('.table-row')
        .filter(function() {
            return d3.select(this).attr('data-ticker') === ticker;
        })
        .classed('selected', true);

    // Scroll the selected row into view
    const selectedRow = document.querySelector('.table-row.selected');
    if (selectedRow) {
        selectedRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
}

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', init);

